'use strict';
let ponytailMode='off',ponyData=null,playwrightEnabled=false,gateway=null,directConnection=null,pluginSession=null,pluginConversation=null,pendingToolDecision=null,gatewayAttempt=0;
const pluginEl=id=>document.getElementById(id);
try{const saved=storage.getItem('relay-ponytail');if(['off','lite','full','ultra'].includes(saved))ponytailMode=saved;pluginEl('gatewayUrl').value=storage.getItem('relay-gateway-url')||''}catch{}
pluginEl('ponyMode').value=ponytailMode;
async function ponytailData(){if(!ponyData){const response=await fetch('./plugins/ponytail.json');if(!response.ok)throw Error('Ponytail skill data could not be loaded. Reconnect and reload Relay.');ponyData=await response.json()}return ponyData}
function pluginNotice(){const bits=[];if(ponytailMode!=='off')bits.push('Ponytail · '+ponytailMode);if(playwrightEnabled)bits.push('Playwright · approval required');pluginEl('pluginNotice').hidden=!bits.length;pluginEl('pluginNotice').textContent=bits.join('  /  ')}
async function preparePluginMessages(messages){const command=messages.at(-1)?.content.match(/^\/(ponytail-review|ponytail-audit|ponytail-debt|ponytail-gain|ponytail-help)\b/);if(ponytailMode==='off'&&!command)return messages;const data=await ponytailData();let instructions=ponytailMode==='off'?'':data.modes[ponytailMode];if(command)instructions+='\n\n'+data.skills[command[1]];return [{role:'system',content:'Enabled plugin instructions follow. They guide responses but do not grant access to files, tools, accounts, or actions. Never claim unperformed actions. Claude-specific hooks, band, metrics and subagents are unavailable in Relay. Whole-repository review needs repository content supplied in chat; only browser tools are exposed by this gateway.\n\n'+instructions},...messages]}
function handlePluginCommand(text){const match=text.match(/^\/ponytail(?:\s+(lite|full|ultra|off))?\s*$/);if(!match)return false;ponytailMode=match[1]||(ponytailMode==='off'?'full':ponytailMode);pluginEl('ponyMode').value=ponytailMode;try{storage.setItem('relay-ponytail',ponytailMode)}catch{}pluginNotice();toast('Ponytail: '+ponytailMode);return true}
async function gatewayRequest(path,body,signal,connection=gateway,method='POST'){if(!connection)throw Error('Connect the plugin gateway first.');return timedFetch(connection.url+path,{method,headers:{Authorization:'Bearer '+connection.token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal},path==='/v1/status'?15000:330000,async response=>{const data=await response.json();if(!response.ok)throw Error(data.error||'Plugin gateway returned HTTP '+response.status);return data})}
async function closePluginSession(){const id=pluginSession;pluginSession=null;pluginConversation=null;if(id&&gateway)await gatewayRequest('/v1/session',{session:id},undefined,gateway,'DELETE').catch(()=>{})}
function disableBrowserPlugin(){if(!playwrightEnabled)return;playwrightEnabled=false;pluginEl('playwrightEnabled').checked=false;void closePluginSession();if(directConnection){models=directConnection.models;config=directConnection.config;updateConnection();if(models.includes(directConnection.model))pluginEl('model').value=directConnection.model;directConnection=null}pluginNotice()}
pluginEl('pluginNav').onclick=()=>{openDialog(pluginEl('pluginsGuide'));document.body.classList.remove('sidebar-open');if(typeof setSidebar==='function')setSidebar(false)};
pluginEl('closePlugins').onclick=()=>closeDialog(pluginEl('pluginsGuide'));
pluginEl('ponyMode').onchange=async()=>{const candidate=pluginEl('ponyMode').value;try{if(candidate!=='off')await ponytailData();ponytailMode=candidate;try{storage.setItem('relay-ponytail',candidate)}catch{}pluginNotice()}catch(error){pluginEl('ponyMode').value=ponytailMode;toast(error.message)}};
pluginEl('connectGateway').onclick=async()=>{if(busy||connecting)return toast('Finish the current reply or connection check first.');const attempt=++gatewayAttempt;pluginEl('connectGateway').disabled=true;try{const url=pluginEl('gatewayUrl').value.trim().replace(/\/+$/,'');const parsed=new URL(url);if(parsed.protocol!=='https:'||parsed.username||parsed.password||parsed.search||parsed.hash)throw Error('Use an HTTPS gateway base URL without credentials or query parameters.');const token=pluginEl('gatewayToken').value.trim();if(!token)throw Error('Enter the gateway access token.');const candidate={url,token};const result=await gatewayRequest('/v1/status',undefined,undefined,candidate,'GET');if(!Array.isArray(result.models)||!result.models.length||!result.plugins?.includes('playwright'))throw Error('This server is not a ready Relay plugin gateway.');if(attempt!==gatewayAttempt)return;if(busy||connecting)throw Error('The workspace became busy. Finish its reply and reconnect the gateway.');const readyModels=result.models.filter(v=>typeof v==='string'&&v.length>0&&v.length<=200);if(!readyModels.length)throw Error('The gateway returned no valid model names.');disableBrowserPlugin();gateway={...candidate,models:readyModels};try{storage.setItem('relay-gateway-url',url)}catch{}pluginEl('playwrightEnabled').disabled=false;pluginEl('gatewayStatus').textContent='Gateway connected. Enable Playwright and choose an Ollama model that supports tools.'}catch(error){pluginEl('gatewayStatus').textContent=error.message}finally{pluginEl('connectGateway').disabled=false}};
pluginEl('playwrightEnabled').onchange=()=>{const checked=pluginEl('playwrightEnabled').checked;if(busy||connecting){pluginEl('playwrightEnabled').checked=playwrightEnabled;return toast('Finish the current reply or connection check first.')}if(!checked){disableBrowserPlugin();return}if(!gateway)return;stopVoiceForNavigation();directConnection={models:[...models],config:{...config},model:pluginEl('model').value};models=[...gateway.models];config={url:gateway.url,token:''};playwrightEnabled=true;updateConnection();pluginEl('serverLabel').textContent='Plugin gateway connected';pluginEl('serverSub').textContent='Playwright · '+new URL(gateway.url).host;pluginNotice()};
function approveTools(approval,signal){return new Promise((resolve,reject)=>{const dialog=pluginEl('toolApproval'),box=pluginEl('toolCalls');box.replaceChildren();for(const call of approval.calls){const heading=document.createElement('b'),pre=document.createElement('pre');heading.textContent=call.name;pre.textContent=JSON.stringify(call.arguments,null,2);box.append(heading,pre)}let finished=false;function finish(value){if(finished)return;finished=true;signal?.removeEventListener('abort',abort);pendingToolDecision=null;closeDialog(dialog);resolve(value)}function abort(){if(finished)return;finished=true;pendingToolDecision=null;closeDialog(dialog);reject(new DOMException('Stopped','AbortError'))}pendingToolDecision=finish;pluginEl('approveTools').onclick=()=>finish(true);pluginEl('declineTools').onclick=()=>finish(false);pluginEl('closeToolApproval').onclick=()=>finish(false);dialog.onclose=()=>{if(!dialog.open)finish(false)};signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted){abort();return}openDialog(dialog)})}
function showToolEvents(events){for(const event of events||[]){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=event.name+(event.approved===false?' · declined':event.isError?' · failed':' · completed');details.append(summary);for(const content of event.content||[]){if(content.type==='text'){const pre=document.createElement('pre');pre.textContent=content.text;details.append(pre)}else if(content.type==='image'&&['image/png','image/jpeg','image/webp'].includes(content.mimeType)){const img=document.createElement('img');img.src='data:'+content.mimeType+';base64,'+content.data;img.alt='Playwright screenshot';details.append(img)}}pluginEl('toolActivity').append(details);const old=pluginEl('toolActivity').querySelectorAll('details');if(old.length>10)old[0].remove()}pluginEl('toolActivity').hidden=pluginEl('toolActivity').childElementCount<=1}
async function pluginChat(messages,signal){if(pluginConversation!==active){await closePluginSession();pluginConversation=active;pluginEl('toolActivity').querySelectorAll('details').forEach(e=>e.remove());pluginEl('toolActivity').hidden=true}try{let response=await gatewayRequest('/v1/chat',{session:pluginSession,model:pluginEl('model').value,messages},signal);pluginSession=response.session;for(let step=0;step<9;step++){showToolEvents(response.events);if(response.done)return response.content;if(!response.approval)throw Error('Gateway returned no result or tool approval.');const allow=await approveTools(response.approval,signal);response=await gatewayRequest('/v1/continue',{session:pluginSession,approvalId:response.approval.id,allow},signal)}throw Error('Plugin step limit reached. Send a new instruction.')}catch(error){await closePluginSession();throw error}}
pluginEl('disconnectGateway').onclick=()=>{if(busy)return toast('Stop the current reply first.');gatewayAttempt++;disableBrowserPlugin();gateway=null;pluginEl('gatewayToken').value='';pluginEl('playwrightEnabled').disabled=true;pluginEl('gatewayStatus').textContent='Gateway disconnected. Proxy token cleared.'};
pluginNotice();
